{
  "tool": "make_docs_operation_domains",
  "source": "mcp",
  "result": [
    {
      "name": "prd",
      "commands": [
        {
          "id": "prd.authority.validate",
          "summary": "Validate that active PRDs describe product authority rather than editorial change operations.",
          "mutates": false,
          "status": "active"
        }
      ]
    },
    {
      "name": "performance",
      "commands": [
        {
          "id": "performance.evidence.validate",
          "summary": "Validate Performance Evidence structure and traceability without running a benchmark or changing repository state.",
          "mutates": false,
          "status": "active"
        }
      ]
    },
    {
      "name": "project",
      "commands": [
        {
          "id": "project.state.status",
          "summary": "Read installation state and the next safe action from the global Store.",
          "mutates": false,
          "status": "active"
        },
        {
          "id": "project.state.recover",
          "summary": "Resume or roll back one verified pending installation operation.",
          "mutates": true,
          "status": "active"
        },
        {
          "id": "project.surface.ensure",
          "summary": "Ensure one selected project support surface and its configured routers.",
          "mutates": true,
          "status": "active"
        },
        {
          "id": "project.path-hygiene.validate",
          "summary": "Check local documentation paths.",
          "mutates": false,
          "status": "active"
        },
        {
          "id": "project.path-hygiene.repair",
          "summary": "Preview or apply repairs to current-project paths in documentation.",
          "mutates": true,
          "status": "active"
        },
        {
          "id": "project.persona.list",
          "summary": "Read the effective project audiences without the Store.",
          "mutates": false,
          "status": "active"
        },
        {
          "id": "project.layout.preview",
          "summary": "Preview exact legacy file destinations, links and blockers without writes.",
          "mutates": false,
          "status": "active"
        },
        {
          "id": "project.layout.prepare",
          "summary": "Save a reviewed CLI or manual layout plan in the Store before file changes.",
          "mutates": true,
          "status": "active"
        },
        {
          "id": "project.layout.apply",
          "summary": "Apply and verify one prepared CLI layout operation.",
          "mutates": true,
          "status": "active"
        },
        {
          "id": "project.layout.verify",
          "summary": "Check a prepared manual layout and record verified completion.",
          "mutates": true,
          "status": "active"
        }
      ]
    },
    {
      "name": "work",
      "commands": [
        {
          "id": "work.item.resolve",
          "summary": "Resolve a coordinate or path to the canonical work-item identity (repo root, wave slug, phase path).",
          "mutates": false,
          "status": "active"
        },
        {
          "id": "work.evidence.record",
          "summary": "Record one work-execution evidence entry in the global store, keyed to the canonical work-item identity.",
          "mutates": true,
          "status": "active"
        },
        {
          "id": "work.evidence.read",
          "summary": "Read recorded work-execution evidence from the global store for a phase identity or a whole wave.",
          "mutates": false,
          "status": "active"
        },
        {
          "id": "work.backlog.snapshot",
          "summary": "Read every live and archived work record into the version 1 deterministic backlog snapshot.",
          "mutates": false,
          "status": "active"
        },
        {
          "id": "work.backlog-cache.lookup",
          "summary": "Read exact reusable per-record backlog review fragments from the optional Global Store cache.",
          "mutates": false,
          "status": "active"
        },
        {
          "id": "work.backlog-cache.write",
          "summary": "Save validated per-record backlog review fragments in the optional rebuildable Global Store cache.",
          "mutates": true,
          "status": "active"
        }
      ]
    },
    {
      "name": "resource",
      "commands": [
        {
          "id": "resource.list",
          "summary": "List the stable system-resource URI inventory with resolution provenance.",
          "mutates": false,
          "status": "active"
        },
        {
          "id": "resource.read",
          "summary": "Read one system resource with exact bytes, media type, and provenance.",
          "mutates": false,
          "status": "active"
        },
        {
          "id": "resource.ensure",
          "summary": "Materialize one selected managed projection under explicit write permission.",
          "mutates": true,
          "status": "active"
        }
      ]
    },
    {
      "name": "lifecycle",
      "commands": [
        {
          "id": "lifecycle.start",
          "summary": "Start a general lifecycle run in the global Store.",
          "mutates": true,
          "status": "active"
        },
        {
          "id": "lifecycle.show",
          "summary": "Show one current general lifecycle run and its evidence references.",
          "mutates": false,
          "status": "active"
        },
        {
          "id": "lifecycle.list",
          "summary": "List current general lifecycle runs for one manifest-minted project.",
          "mutates": false,
          "status": "active"
        },
        {
          "id": "lifecycle.checkpoint",
          "summary": "Record a lifecycle checkpoint with explicit optimistic concurrency.",
          "mutates": true,
          "status": "active"
        },
        {
          "id": "lifecycle.pause",
          "summary": "Pause an active lifecycle run.",
          "mutates": true,
          "status": "active"
        },
        {
          "id": "lifecycle.resume",
          "summary": "Resume a paused lifecycle run.",
          "mutates": true,
          "status": "active"
        },
        {
          "id": "lifecycle.attach-evidence",
          "summary": "Attach one bounded evidence reference to a lifecycle run.",
          "mutates": true,
          "status": "active"
        },
        {
          "id": "lifecycle.complete",
          "summary": "Complete a lifecycle run.",
          "mutates": true,
          "status": "active"
        },
        {
          "id": "lifecycle.fail",
          "summary": "Fail a lifecycle run.",
          "mutates": true,
          "status": "active"
        },
        {
          "id": "lifecycle.abandon",
          "summary": "Abandon a lifecycle run.",
          "mutates": true,
          "status": "active"
        }
      ]
    },
    {
      "name": "uat",
      "commands": [
        {
          "id": "uat.scenario.validate",
          "summary": "Validate Unassisted Goal Testing records against repository evidence. Human judgments remain with the recorded assessor.",
          "mutates": false,
          "status": "active"
        },
        {
          "id": "uat.persona.resolve",
          "summary": "Validate Unassisted Goal Testing records against repository evidence. Human judgments remain with the recorded assessor.",
          "mutates": false,
          "status": "active"
        },
        {
          "id": "uat.target.validate",
          "summary": "Validate Unassisted Goal Testing records against repository evidence. Human judgments remain with the recorded assessor.",
          "mutates": false,
          "status": "active"
        },
        {
          "id": "uat.evidence-reference.validate",
          "summary": "Validate Unassisted Goal Testing records against repository evidence. Human judgments remain with the recorded assessor.",
          "mutates": false,
          "status": "active"
        },
        {
          "id": "uat.finding.validate",
          "summary": "Validate Unassisted Goal Testing records against repository evidence. Human judgments remain with the recorded assessor.",
          "mutates": false,
          "status": "active"
        },
        {
          "id": "uat.result.validate",
          "summary": "Validate Unassisted Goal Testing records against repository evidence. Human judgments remain with the recorded assessor.",
          "mutates": false,
          "status": "active"
        }
      ]
    }
  ]
}

